style.css:
@-moz-document url-prefix("https://www.roblox.com") {
.theme-dark, .theme-light, .rbx-header {
    background-image: url("https://i.postimg.cc/8z34WTQd/2CA43D09-3B38-4411-AB9A-D8B69C47C7D4.jpg") !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center !important;
  }

  /* Makes the boxes transparent so you can see her photo */
  .content, .section-content, .container-main {
    background: rgba(0, 0, 0, 0.4) !important;
    border: none !important;
  }
}
